// 参考解：尾插法建表 + 遍历输出
#include <iostream>
using namespace std;

struct LNode {
    int data;
    LNode *next;
};

typedef LNode *LinkList;

int main() {
    int n;
    if (!(cin >> n)) return 0;

    LinkList L = new LNode;
    L->next = nullptr;
    LNode *r = L;
    int len = 0;

    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        LNode *s = new LNode;
        s->data = x;
        s->next = nullptr;
        r->next = s;
        r = s;
        len++;
    }

    cout << len << "\n";
    if (L->next == nullptr) {
        cout << "empty\n";
    } else {
        int printed = 0;
        for (LNode *p = L->next; p != nullptr; p = p->next) {
            cout << p->data;
            printed++;
            cout << (printed == len ? '\n' : ' ');
        }
    }
    return 0;
}
